<script setup lang="ts">
import { useReceptionForm } from "../../composables/useReceptionForm";
const { historyNotes,receivedLabel,priceLabel,depositLabel,store, draft, price, deposit, method, canEdit, canPay, folio, showPassword, togglePassword, editing,editExisting,changePassword,submit } = useReceptionForm();
const equipmentFields = [{ key: "item", id: "art", label: "Artículo", required: true }, { key: "brand", id: "marca", label: "Marca" }, { key: "model", id: "modelo", label: "Modelo" }, { key: "serial", id: "serie", label: "No. de serie" }] as const;
</script>
<template>
  <form id="reception-form" class="form" @submit.prevent="submit">
    <section class="block client-block" aria-labelledby="client-title"><h2 id="client-title" class="sec">Cliente</h2>
      <div class="g2"><div class="fld"><label for="orden">Orden</label><input id="orden" :value="folio" readonly maxlength="100"></div><div class="fld"><label for="fecha">Fecha de recepción</label><input v-if="editing" id="fecha" v-model="draft.receivedAt" :readonly="!canEdit" maxlength="100" required><input v-else id="fecha" :value="receivedLabel" readonly></div></div>
      <div class="g2"><div class="fld"><label for="cliente">Cliente</label><input id="cliente" v-model="draft.client.fullName" :readonly="!canEdit" maxlength="100" required autocomplete="name"></div><div class="fld"><label for="tel">Teléfono</label><input id="tel" v-model="draft.client.phone" :readonly="!canEdit" type="tel" maxlength="100" required autocomplete="tel"></div></div>
    </section>
    <section class="block equipment-block" aria-labelledby="equipment-title"><h2 id="equipment-title" class="sec">Artículo</h2>
      <div class="g2"><div v-for="item in equipmentFields" :key="item.key" class="fld"><label :for="item.id">{{ item.label }}</label><input :id="item.id" v-model="draft.equipment[item.key]" :readonly="!canEdit" maxlength="100" :required="'required' in item && item.required"></div></div>
      <div class="fld"><label for="equipment-history">Antecedentes del equipo</label><textarea id="equipment-history" v-model="historyNotes" :readonly="!canEdit" maxlength="16000" rows="4" aria-describedby="equipment-history-help"></textarea><p id="equipment-history-help" class="help">Describe visitas a otros talleres, caídas, golpes, humedad o cualquier antecedente relevante.</p></div>
      <label v-if="editExisting" class="history-check"><input v-model="changePassword" type="checkbox" :disabled="!canEdit">Cambiar contraseña del equipo</label><div class="fld" :class="{ 'stored-device-password': !editing && store.currentOrder?.hasDevicePassword }"><label for="pass">Contraseña del equipo</label><input id="pass" v-model="draft.devicePassword" :readonly="!canEdit || (editExisting && !changePassword)" :type="!editing && showPassword ? 'text' : 'password'" maxlength="100" autocomplete="off" :placeholder="!editing && store.currentOrder?.hasDevicePassword ? 'Contraseña guardada' : ''"><button v-if="!editing" type="button" class="eye" :class="{ revealed: showPassword }" :aria-pressed="showPassword" :aria-label="showPassword ? 'Ocultar contraseña del equipo' : 'Consultar contraseña del equipo'" aria-controls="pass" :disabled="store.isLoading || !store.currentOrder?.hasDevicePassword" @click="togglePassword"><svg class="i" viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle v-if="showPassword" cx="12" cy="12" r="3"/><path v-else d="m3 3 18 18"/></svg></button></div>
    </section>
    <section class="block work-block" aria-labelledby="work-title"><h2 id="work-title" class="sec">Trabajo</h2>
      <div class="fld"><label for="trabajo">Trabajo a realizar</label><textarea id="trabajo" v-model="draft.plannedWork" :readonly="!canEdit" maxlength="16000" rows="2"></textarea></div>
      <div class="g2"><div class="fld"><label for="costo">Costo aproximado</label><input v-if="editing" id="costo" v-model="price" :readonly="!canEdit" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" maxlength="16" required><input v-else id="costo" :value="priceLabel" readonly></div><div class="fld"><label for="abono">{{ editing && !editExisting ? 'Abono inicial' : 'Cobro neto' }}</label><input v-if="editing" id="abono" v-model="deposit" :readonly="!canPay" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" maxlength="16" required><input v-else id="abono" :value="depositLabel" readonly></div></div>
      <details class="reception-details" :open="editing" @invalid.capture="($event.currentTarget as HTMLDetailsElement).open = true"><summary>Falla reportada</summary><div class="fld"><label class="sr" for="falla">Falla reportada</label><textarea id="falla" v-model="draft.reportedFailure" :readonly="!canEdit" maxlength="16000" rows="2" required></textarea></div></details>
      <div v-if="editing && !editExisting" class="fld"><label for="deposit-method">Método del abono inicial</label><input id="deposit-method" v-model="method" :readonly="!canPay" maxlength="200" placeholder="Escribe el método si registras un abono"><p class="help">Método libre. Registrar un abono requiere su permiso específico.</p></div>
    </section>
    <section class="block notes-block" aria-labelledby="notes-title"><h2 id="notes-title" class="sec">Notas</h2><div class="fld"><label class="sr" for="notas">Notas de recepción</label><textarea id="notas" v-model="draft.receptionNotes" :readonly="!canEdit" maxlength="16000" rows="3"></textarea></div></section>
  </form>
</template>
